{
  "PROP-6a4369e9-inv-009": {
    "property_id": "PROP-6a4369e9-inv-009",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-009",
      "classification": "vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_column_verification.rs::verify_data_column_sidecar::L532-561",
      "proof_trace": "Block verification enforces max_blobs_per_block(epoch) runtime check (block_verification.rs:883-886), but data column gossip verification omits this check entirely\u2014only verifying cells==commitments==proofs length consistency, not the epoch-specific upper bound.",
      "attack_scenario": "Attacker crafts data column sidecar with kzg_commitments.len() > max_blobs_per_block for the epoch (e.g., 9 commitments when epoch limit is 6). SSZ VariableList accepts up to MaxBlobCommitmentsPerBlock=4096. The data column passes gossip verification and propagates, causing resource exhaustion or consensus inconsistency when peers process oversized columns that would be rejected during block verification.",
      "checklist_id": "PROP-6a4369e9-inv-009"
    },
    "text": "kzg_commitments count must not exceed max_blobs_per_block for the sidecar's epoch.",
    "assertion": "forall sidecar: len(sidecar.kzg_commitments) <= get_blob_parameters(epoch).max_blobs_per_block",
    "covers": "SG-002",
    "severity": "HIGH",
    "type": "invariant"
  }
}

